def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    # expired, treat as absent
                    del cache[key]
            if key in cache:
                # update existing entry, refresh write time, move to end (MRU)
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)  # evict LRU
                cache[key] = (value, t)
        else:
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(v)
                    cache.move_to_end(key)
            else:
                results.append(-1)
    return results

